private static IEnumerable<AttributeData> get_attributes(ISymbol member)
{
    HashSet<ISymbol> visited = new(SymbolEqualityComparer.Default);
    foreach (ISymbol symbol in GetRelatedSymbols(member))
    {
        foreach (ISymbol part in GetParts(symbol))
        {
            if (!visited.Add(part))
                continue;

            foreach (AttributeData attribute in part.get_attributes())
                yield return attribute;
        }
    }
}
